// KROK 1: nowa instancja obiektu Tomcat - "silnik", jeszcze nieuruchomiony.
Tomcat tomcat = new Tomcat();

// KROK 2: katalog bazowy (baseDir) - MUSI istniec. Files.createTempDirectory
// sam tworzy katalog i zwraca do niego Path.
Path baseDir = Files.createTempDirectory("lesson03");
tomcat.setBaseDir(baseDir.toString());

// KROK 3: port 0 - "wybierz dowolny WOLNY port". getConnector() trzeba
// wywolac PRZED tomcat.start().
tomcat.getConnector().setPort(0);

// KROK 4: kontekst aplikacji - "" oznacza kontekst glowny (root).
Context context = tomcat.addContext("", null);

// KROK 5: rejestracja serwletu - nazwa sluzy tylko do identyfikacji
// wewnatrz kontenera (np. w logach), NIE jest czescia URL-a.
Tomcat.addServlet(context, "configServlet", new SetupInfoServlet());

// KROK 6: mapowanie URL -> serwlet - dopiero to mowi kontenerowi,
// pod jaka sciezka serwlet ma odpowiadac. Bez tego kroku serwlet
// byłby zarejestrowany, ale NIEOSIAGALNY.
context.addServletMappingDecoded("/setup", "configServlet");

try {
    // KROK 7: dopiero teraz serwer faktycznie zaczyna nasluchiwac.
    tomcat.start();
    int port = tomcat.getConnector().getLocalPort();
    // ... wyslij zadanie HTTP ...
} finally {
    // KROK 8: try/finally jest KLUCZOWE - zawsze zwolnij zasoby.
    tomcat.stop();
    tomcat.destroy();
}

