// setBaseDir: katalog roboczy Tomcata
// setPort(0): system wybierze wolny port
// addContext: kontekst glowny aplikacji
// addServlet: rejestracja serwletu
// addServletMappingDecoded: mapowanie URL -> serwlet
// start(): rozpoczecie nasluchiwania
// stop()+destroy(): zwolnienie zasobow
